'use strict';
const MIN_DEMO_INVESTMENT=250;
const validDemoInvestment=value=>Number.isFinite(value)&&value>=MIN_DEMO_INVESTMENT&&value<=1e7&&Math.abs(value*100-Math.round(value*100))<.00001;
const defaultTiers=()=>[{id:'single',name:'Single',count:1,rate:3},{id:'network',name:'Network',count:3,rate:5.6},{id:'portfolio',name:'Portfolio',count:5,rate:7.9},{id:'scale',name:'Scale',count:10,rate:11.2}];
function ensureTariffs(){if(!Array.isArray(demo.sessions))demo.sessions=[];if(!('plan' in demo))demo.plan=null;if(demo.tariffModelVersion!==2){demo.tariffs=defaultTiers();demo.sessions.forEach(s=>s.period??='session');if(demo.plan){const t=demo.tariffs.find(t=>t.id===demo.plan.tierId)||demo.tariffs[0];demo.plan.rate=t.rate;demo.plan.period='week'}demo.tariffModelVersion=2}else if(!Array.isArray(demo.tariffs)||demo.tariffs.length!==4)demo.tariffs=defaultTiers()}
ensureTariffs();
let chosenTier=demo.plan?.tierId||'single',investmentDraft=demo.plan?.capital||250,chosenStations=demo.plan?.stationIds?.slice()||[371815];
let stationPickerQuery='';
const oldRenderNav=renderNav;
renderNav=function(){oldRenderNav();$('.main-nav').insertAdjacentHTML('beforeend',`<button class="nav-item ${((role==='admin'?adminTab:tab)==='tariffs')?'active':''}" data-tab="tariffs">${icon('zap')}<span>Tariffs</span></button>`)};
const oldRenderClientTab=renderClientTab;
renderClientTab=function(){oldRenderClientTab();let panel=$('#tariffs-section');if(!panel){panel=document.createElement('section');panel.id='tariffs-section';$('#client-view').append(panel)}panel.hidden=tab!=='tariffs';if(tab==='tariffs')renderTariffs();renderPlanBar()};
const oldRenderAdmin=renderAdmin;
renderAdmin=function(){ensureTariffs();oldRenderAdmin();if(adminTab==='tariffs'){$('#admin-view .admin-layout>div').innerHTML=tariffAdmin()}else if(adminTab==='overview'){$('#admin-view .admin-layout>div').insertAdjacentHTML('beforeend',`<section class="panel admin-section"><h2>${icon('zap')} TARIFF MANAGEMENT</h2><p class="muted">Edit weekly demo rates and simulate accruals.</p><button class="button secondary" data-action="manage-tariffs">Manage weekly plans</button></section>`)}renderNav()};
const oldRenderNumbers=renderNumbers;
renderNumbers=function(){oldRenderNumbers();renderPlanBar()};
function renderPlanBar(){ensureTariffs();if(!$('#plan-shortcut')){$('.metrics-grid').insertAdjacentHTML('afterend','<div id="plan-shortcut" class="plan-shortcut"></div>')}const plan=demo.plan;$('#plan-shortcut').hidden=tab!=='dashboard';$('#plan-shortcut').innerHTML=plan?`<span>${icon('zap')} <strong>${escapeHtml(plan.name)}</strong><span>${plan.stationIds.length} stations · ${plan.rate.toFixed(1)}% per week</span></span><span class="plan-capital">Demo allocation: <strong>${money(plan.capital)}</strong></span><button data-action="tariffs">Manage plan ${icon('arrow')}</button>`:`<span>${icon('zap')} <strong>Choose your Eco-Charge plan</strong><span>1, 3, 5 or 10 charging stations</span></span><button data-action="tariffs">Explore tariffs ${icon('arrow')}</button>`;
 if(plan){const total=demo.sessions.reduce((n,s)=>n+s.payout,0);const last=demo.sessions.at(-1)?.payout||0;$('.metrics-grid .metric-card:last-child>strong').textContent=money(total);$('.metrics-grid .metric-card:last-child>span').textContent='Demo accruals';$('.metrics-grid .metric-card:last-child>small').textContent='USD · simulated';$('.yield-summary>strong').textContent=`+${money(last)}`;$('.yield-summary>span').textContent='Last demo session';$('.performance-card .card-heading').firstChild.textContent='WEEKLY ACCRUAL PERFORMANCE ';renderSessionChart()}
}
function renderSessionChart(){if(!demo.plan)return;let sum=0;const values=demo.sessions.map(s=>sum+=s.payout);if(!values.length)values.push(0);const max=Math.max(...values,1);const padded=[0,...values];const path=padded.map((v,i)=>`${i?'L':'M'}${40+i/(padded.length-1)*372} ${130-v/max*99}`).join(' ');for(const id of ['#chart-line','#chart-shadow'])$(id).setAttribute('d',path);$('#chart-area').setAttribute('d',path+' L412 138 L40 138Z');const labels=$$('#yield-chart .chart-labels text');[max,max*.75,max*.5,max*.25,0].forEach((n,i)=>labels[i].textContent='$'+n.toFixed(0));const cy=130-values.at(-1)/max*99;$('#yield-chart>circle').setAttribute('cy',String(cy));$('#yield-chart g[transform] text').textContent=money(values.at(-1));$('.chart-dates').innerHTML='<span>Start</span><span>Simulated weeks</span><span>Latest</span>';$('.period-button').innerHTML='Accrual history <span>↗</span>';$('.period-button').dataset.action='sessions'}
function normalizeSelection(tier){if(!stations.length)return;chosenStations=chosenStations.filter(id=>stations.some(s=>s.id===id)).slice(0,tier.count);if(chosenStations.length<tier.count){const preferred=[selected?.id,...demo.portfolio,...stations.map(s=>s.id)].filter(Boolean);for(const id of preferred){if(!chosenStations.includes(id))chosenStations.push(id);if(chosenStations.length===tier.count)break}}}
function renderTariffs(){ensureTariffs();const tier=demo.tariffs.find(t=>t.id===chosenTier)||demo.tariffs[0];normalizeSelection(tier);$('#tariffs-section').innerHTML=`<section class="panel tariff-hero"><div><span class="eyebrow">ECO-CHARGE / DEMO PLANS</span><h1>Build your sample plan.</h1><p>Choose reference locations. Review an illustrative weekly calculation.</p></div><div class="tariff-unit"><strong>Per week</strong><span>On total allocated capital</span></div></section><div class="tariff-grid">${demo.tariffs.map(t=>`<button class="panel tariff-card ${t.id===tier.id?'selected':''}" data-tier="${t.id}" aria-pressed="${t.id===tier.id}"><span class="tier-name">${t.name}</span><span class="tier-stations">${t.count}<small>${t.count===1?'charging station':'charging stations'}</small></span><span class="tier-rate">${t.rate.toFixed(1)}<small>%</small></span><span class="tier-per">per week</span><span class="tier-allocation">Rate applies to the total<br>capital in your demo plan.</span><span class="tier-choose">${t.id===tier.id?'Selected':'Choose plan'} ${t.id===tier.id?'✓':'→'}</span></button>`).join('')}</div><div class="tariff-workspace"><section class="panel allocation-panel"><div class="section-heading"><h2>YOUR DEMO ALLOCATION</h2><span>${tier.name} · ${tier.count} stations</span></div><label for="investment-amount">Your demo amount (USD)</label><p class="investment-help" id="investment-help">Enter any amount from $250. The station group sets the rate; the amount updates your weekly illustration.</p><div class="investment-field"><span>$</span><input id="investment-amount" aria-describedby="investment-help tariff-error" type="number" inputmode="decimal" min="250" max="10000000" step="0.01" value="${investmentDraft}"></div><div class="investment-presets" role="group" aria-label="Choose a demo amount">${[250,500,1000].map(value=>`<button type="button" data-investment-preset="${value}" aria-pressed="${value===investmentDraft}">${money(value)}</button>`).join('')}</div><div class="allocation-math"><div><span>Allocated to each station</span><strong id="allocation-each">—</strong></div><div><span>Weekly rate</span><strong>${tier.rate.toFixed(1)}%</strong></div><div class="allocation-total"><span>Weekly accrual<br>on total allocated capital</span><strong id="allocation-payout" role="status" aria-live="polite">—</strong></div></div><div class="formula-box">Total investment × ${tier.rate.toFixed(1)}% = weekly accrual</div><p class="tariff-disclosure">Demonstration of your proposed model. Weekly accruals are simulated and do not establish actual profit. These rates are not verified returns from Electrify America.</p><button class="button primary" data-action="apply-plan">Apply demo plan ${icon('arrow')}</button><div class="form-error" id="tariff-error" role="alert"></div></section><section class="panel station-picker"><div class="section-heading"><h2>SELECT CHARGING STATIONS</h2><span id="selection-count">${chosenStations.length} / ${tier.count} selected</span></div><p class="muted picker-note">Real public locations are used to test selection. They are not established assets of ECO CHARGE.</p><input id="picker-search" placeholder="Search city, state or station ID…" aria-label="Find station for demo plan"><div id="picker-results">${pickerRows(tier)}</div></section></div><section class="panel tariff-scenarios"><div class="section-heading"><h2>WEEKLY SCENARIOS</h2><span>Illustrations, not traffic forecasts</span></div><p>Simple accrual on the same total capital. No compounding or reinvestment is assumed.</p><div class="scenario-grid" id="scenario-results"></div><div class="scenario-footnote">The weekly rate applies once to your total capital. The number of stations does not multiply your invested amount.</div></section><section class="panel session-panel"><div class="section-heading"><h2>DEMO ACCRUAL HISTORY</h2><button class="table-button" data-action="simulate-session">Simulate a week</button></div>${sessionRows()}</section>`;updateTariffMath()}
function pickerRows(tier){const q=stationPickerQuery.toLowerCase().trim();const rows=q?stations.filter(s=>`${s.name} ${s.city} ${s.state} ${s.id}`.toLowerCase().includes(q)).slice(0,20):[...chosenStations.map(id=>stations.find(s=>s.id===id)).filter(Boolean),...stations.filter(s=>!chosenStations.includes(s.id)).slice(0,6)];return rows.length?rows.map(s=>`<label class="picker-row"><input type="checkbox" data-pick-station="${s.id}" ${chosenStations.includes(s.id)?'checked':''}><span><strong>${escapeHtml(s.city)}, ${s.state}</strong><small>${escapeHtml(s.name)}</small></span><span>${s.ports} ports<br><small>AFDC ${s.id}</small></span></label>`).join(''):'<div class="empty-state">No matching stations.</div>'}
function updateTariffMath(){const tier=demo.tariffs.find(t=>t.id===chosenTier);if(!tier||!$('#investment-amount'))return;investmentDraft=Number($('#investment-amount').value);const valid=Number.isFinite(investmentDraft)&&validDemoInvestment(investmentDraft);const each=valid?investmentDraft/tier.count:0;$('#allocation-each').textContent=valid?money(each):'—';$('#allocation-payout').textContent=valid?money(each*tier.rate/100):'—';$('#scenario-results').innerHTML=[1,10,100].map(n=>`<div><span>${n} ${n===1?'session':'sessions'} per station</span><strong>${valid?money(investmentDraft*tier.rate/100*n):'—'}</strong><small>${n*tier.count} total sessions · ${((tier.rate*n)).toFixed(1)}% of capital</small></div>`).join('');$('#tariff-error').textContent=valid?'':'Enter a total investment between $250 and $10,000,000.'}
function sessionRows(){ensureTariffs();return demo.sessions.length?`<div class="table-scroll"><table><thead><tr><th>Event</th><th>Station</th><th>Allocated capital</th><th>Rate</th><th>Demo accrual</th></tr></thead><tbody>${demo.sessions.slice().reverse().slice(0,30).map(s=>`<tr><td><strong>Demo charging session</strong><small>${s.id}</small></td><td>${escapeHtml(s.city)}, ${s.state}<small>AFDC ${s.stationId}</small></td><td>${money(s.allocatedCapital)}</td><td>${s.rate.toFixed(1)}%</td><td class="green-text">+${money(s.payout)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No simulated sessions yet. Apply a demo plan, then simulate a completed charging event.</div>'}
function tariffAdmin(){return `<section class="panel admin-section"><div class="section-heading"><h2>TARIFF CONFIGURATION</h2><span>Draft commercial model</span></div><p class="muted">Percent of total plan capital per week. These demo rates are not linked to operating revenue.</p><form id="tariff-admin-form"><div class="table-scroll"><table><thead><tr><th>Plan</th><th>Stations</th><th>Weekly rate</th></tr></thead><tbody>${demo.tariffs.map(t=>`<tr><td>${t.name}</td><td>${t.count}</td><td><div class="rate-input"><input type="number" min="0.01" max="100" step="0.01" name="${t.id}" value="${t.rate}" aria-label="${t.name} rate" required><span>%</span></div></td></tr>`).join('')}</tbody></table></div><div class="form-error" id="rate-error" role="alert"></div><button class="button primary" type="submit">Save demo rates</button></form><p class="muted" style="font-size:12px">Existing plan terms stay unchanged until the client applies a new plan.</p></section><section class="panel admin-section"><h2>ACTIVE CLIENT PLAN</h2>${demo.plan?`<div class="active-plan-admin"><strong>John Doe · ${escapeHtml(demo.plan.name)}</strong><p>${money(demo.plan.capital)} total · ${demo.plan.stationIds.length} stations · ${demo.plan.rate.toFixed(1)}% per week</p><small>Capital is split equally. ${money(demo.plan.capital/demo.plan.stationIds.length)} per station.</small></div><button class="button secondary" data-action="simulate-session">Simulate a week</button>`:'<div class="empty-state">No plan applied. Choose a tariff in the Client portal first.</div>'}</section><section class="panel admin-section"><h2>WEEKLY ACCRUALS</h2>${sessionRows()}</section>`}
actions.tariffs=()=>{setRole('client');tab='tariffs';renderClientTab()};actions['manage-tariffs']=()=>{adminTab='tariffs';renderAdmin()};actions.sessions=()=>openModal(`<h2>Demo session ledger</h2>${sessionRows()}<button class="button primary" data-action="tariffs">Open tariffs & calculator</button>`);
actions.yield=()=>demo.plan?actions.sessions():openModal('<h2>Simulated yield</h2><p>The initial dashboard shows sample data. Choose a tariff to calculate accruals from explicitly simulated charging sessions.</p><button class="button primary" data-action="tariffs">Choose a tariff</button>');
actions['apply-plan']=()=>{const tier=demo.tariffs.find(t=>t.id===chosenTier);updateTariffMath();if(!Number.isFinite(investmentDraft)||investmentDraft<MIN_DEMO_INVESTMENT||investmentDraft>1e7||Math.abs(investmentDraft*100-Math.round(investmentDraft*100))>.00001){$('#tariff-error').textContent='Enter a valid USD amount with no more than two decimal places.';return}if(chosenStations.length!==tier.count){$('#tariff-error').textContent=`Select exactly ${tier.count} charging stations.`;return}openModal(`<h2>Apply ${tier.name} demo plan?</h2><ul class="modal-list"><li><strong>Total simulated capital</strong><small>${money(investmentDraft)}</small></li><li><strong>Selected stations</strong><small>${tier.count} · ${money(investmentDraft/tier.count)} per station</small></li><li><strong>Accrual per week</strong><small>${money(investmentDraft/tier.count*tier.rate/100)} (${tier.rate.toFixed(1)}% of the station allocation)</small></li></ul><div class="modal-note">No funds are transferred. This resets the demo session ledger for the new plan. Previous demo credits are removed from the demo cash balance.</div><button class="button primary" data-action="confirm-plan">Apply demo plan</button>`)};
actions['confirm-plan']=()=>{const tier=demo.tariffs.find(t=>t.id===chosenTier);const previous=demo.sessions.reduce((n,s)=>n+s.payout,0);if(demo.balance-previous<pendingWithdrawals()){toast('Review pending withdrawals before resetting a credited plan.');return}if(demo.balance<previous){toast('Reset the demo before replacing a plan whose credits were withdrawn.');return}demo.balance=Math.round((demo.balance-previous)*100)/100;demo.plan={tierId:tier.id,name:tier.name,rate:tier.rate,capital:investmentDraft,stationIds:chosenStations.slice(),appliedAt:new Date().toISOString()};demo.portfolio=chosenStations.slice();demo.sessions=[];activity(`John Doe applied ${tier.name}: ${tier.count} stations, ${tier.rate}% per demo session`);persist();$('#modal').close();renderMap();renderTariffs();toast('Demo plan applied. No real investment was made.')};
actions['simulate-session']=()=>{if(!demo.plan){toast('Apply a demo tariff first.');return}openModal(`<h2>Simulate a week</h2><p>Choose a station in the active demo plan. This action creates a test event and adds its calculated payout to the demo balance.</p><form id="session-form"><label for="session-station">Charging station</label><select id="session-station">${demo.plan.stationIds.map(id=>stations.find(s=>s.id===id)).filter(Boolean).map(s=>`<option value="${s.id}">${escapeHtml(s.city)}, ${s.state} · AFDC ${s.id}</option>`).join('')}</select><div class="allocation-math"><div><span>Capital allocated to station</span><strong>${money(demo.plan.capital/demo.plan.stationIds.length)}</strong></div><div><span>Demo credit for this session</span><strong class="green-text">${money(demo.plan.capital/demo.plan.stationIds.length*demo.plan.rate/100)}</strong></div></div><div class="modal-note">Not a live charging event. No operating revenue is imported.</div><button class="button primary" type="submit">Create demo session & accrual</button></form>`)};
document.addEventListener('click',e=>{const tierButton=e.target.closest('[data-tier]');if(tierButton){chosenTier=tierButton.dataset.tier;renderTariffs()}if(e.target.closest('[data-action="tariffs"]')&&$('#modal').open)$('#modal').close()});
document.addEventListener('input',e=>{if(e.target.id==='investment-amount')updateTariffMath();if(e.target.id==='picker-search'){stationPickerQuery=e.target.value;$('#picker-results').innerHTML=pickerRows(demo.tariffs.find(t=>t.id===chosenTier))}});
document.addEventListener('change',e=>{if(!e.target.matches('[data-pick-station]'))return;const id=Number(e.target.dataset.pickStation);const tier=demo.tariffs.find(t=>t.id===chosenTier);if(e.target.checked){if(chosenStations.length>=tier.count){e.target.checked=false;toast(`Unselect a station first. This plan includes ${tier.count}.`);return}chosenStations.push(id)}else chosenStations=chosenStations.filter(x=>x!==id);$('#selection-count').textContent=`${chosenStations.length} / ${tier.count} selected`;$('#tariff-error').textContent=chosenStations.length===tier.count?'':`Select ${tier.count-chosenStations.length} more station(s).`});
document.addEventListener('submit',e=>{if(e.target.id==='tariff-admin-form'){e.preventDefault();const values=demo.tariffs.map(t=>Number(e.target.elements.namedItem(t.id).value));if(values.some((v,i)=>!Number.isFinite(v)||v<=0||v>100||(i&&v<=values[i-1]))){$('#rate-error').textContent='Rates must be positive, at most 100%, and increase with station count.';return}demo.tariffs=demo.tariffs.map((t,i)=>({...t,rate:values[i]}));activity('Staff updated demo tariff rates');persist();renderAdmin();toast('Demo tariff rates saved.')}if(e.target.id==='session-form'){e.preventDefault();if(!demo.plan)return;const stationId=Number($('#session-station').value);if(!demo.plan.stationIds.includes(stationId))return;const station=stations.find(s=>s.id===stationId);if(!station)return;const allocatedCapital=demo.plan.capital/demo.plan.stationIds.length;const payout=Math.round(allocatedCapital*demo.plan.rate)/100;demo.sessions.push({id:`SIM-${Date.now().toString(36).toUpperCase()}-${demo.sessions.length+1}`,stationId,city:station.city,state:station.state,allocatedCapital,rate:demo.plan.rate,payout,date:new Date().toISOString()});demo.balance=Math.round((demo.balance+payout)*100)/100;activity(`Simulated charging event at AFDC ${stationId}: +${money(payout)}`);persist();$('#modal').close();if(role==='admin')renderAdmin();else if(tab==='tariffs')renderTariffs();toast(`Demo charging session completed: +${money(payout)}`)}});
const originalReset=actions['confirm-reset'];actions['confirm-reset']=()=>{originalReset();ensureTariffs();chosenTier='single';investmentDraft=250;chosenStations=[371815];stationPickerQuery='';chart();$('.metrics-grid .metric-card:last-child>strong').textContent='$356.18';$('.metrics-grid .metric-card:last-child>span').textContent='Total Yield (30d)';$('.metrics-grid .metric-card:last-child>small').textContent='USD · simulated';$('.yield-summary>strong').innerHTML='+0.82<span>%</span>';$('.yield-summary>span').textContent='Today';$('.period-button').dataset.action='period';$('.period-button').innerHTML='Last 30 days <span>⌄</span>';$('.performance-card .card-heading').firstChild.textContent='WEEKLY YIELD PERFORMANCE ';const labels=['+1.5%','+1.0%','+0.5%','0%','−0.5%'];$$('#yield-chart .chart-labels text').forEach((n,i)=>n.textContent=labels[i]);$('#yield-chart g[transform] text').textContent='+0.82%';$('#yield-chart>circle').setAttribute('cy','57');$('.chart-dates').innerHTML=['Aug 17','Aug 24','Aug 31','Sep 07','Today'].map(s=>`<span>${s}</span>`).join('');renderPlanBar();if(role==='admin')renderAdmin();else if(tab==='tariffs')renderTariffs();persist()};
